NAME = 'Est: Estonian Bible'
BOOK = 'Hebrews'

CHAPTERS = {
    1: {
        1: 'Kui Jumal muiste mitu korda ja mitmel kombel vanemaile oli rääkinud prohvetite kaudu,',
        2: 'siis on Ta neil viimseil päevil meile rääkinud Poja kaudu, Kelle Ta on pannud kõigi asjade pärijaks, Kelle läbi Ta on teinud maailmaajastud,',
        3: 'Kes, olles Tema aupaistus ning Ta olemuse kuju ja kandes kõike Oma vägeva sõnaga, pärast seda kui Ta Iseenese läbi oli toimetanud meie pattude puhastuse, istus Ausuuruse paremale käele kõrguses',
        4: 'ning sai seda ülemaks Inglitest, mida kõrgema nime Ta on pärinud kui nemad.',
        5: 'Sest missugusele Inglile on Ta iganes öelnud: "Sina oled Mu Poeg, täna Ma sünnitasin Sind!", või jälle: "Mina tahan olla Temale Isaks ja Tema peab olema Mulle Pojaks!"?',
        6: 'Ent sellest, kui Ta jälle toob esmasündinu maailma, ütleb Ta: "Ka kõik Jumala Inglid kummardagu Teda!"',
        7: 'Ent Inglitest Ta ütleb küll: "Ta teeb Oma Inglid tuulteks ja Oma teenijad tuleleegiks!"',
        8: 'Aga Pojale Ta ütleb: "Su aujärg, Jumal, on ikka ja igavesti, Su valitsuskepp on õigluse kepp!',
        9: 'Sa armastad õigust ja vihkad ülekohut; sellepärast on Jumal, Sinu Jumal, Sind võidnud rõõmuõliga enam kui Su kaaslasi!"',
        10: 'Ja: "Sina, Issand, panid maale aluse ja taevad on Su käte tööd!',
        11: 'Need hävivad, aga Sina püsid; nad kõik kuluvad nagu kuub',
        12: 'ja Sa rullid nad kokku nagu mantli, nagu kuue, ja nad muudetakse; aga Sina oled seesama ja Sinu aastad ei lõpe!"',
        13: 'Või missugusele Inglile on Ta kunagi öelnud: "Istu Mu paremale käele, kuni Ma panen Su vaenlased Su jalgealuseks järiks!"',
        14: 'Eks nad kõik ole teenijad vaimud, läkitatud abistama neid, kes õndsuse pärivad?',
    },
    2: {
        1: 'Sellepärast tuleb meil palju hoolsamini silmas pidada seda, mida oleme kuulnud, et me kuidagi mööda ei libiseks.',
        2: 'Sest kui Inglite kaudu räägitud sõna püsis kindlana ja kõik üleastumine ja sõnakuulmatus sai oma õige palga,',
        3: 'kuidas me siis võime pääseda pakku, kui me ei hooli nii suurest päästest, mis oma kuulutuse alguse sai Issandalt ja mille kinnitasid meisse need, kes seda kuulsid,',
        4: 'kui Jumal ühes nendega andis tunnistust tunnustähtedega ja imedega ja mõnesuguste vägevate tegudega ja Püha Vaimu jagamistega Oma tahte järgi.',
        5: 'Sest mitte Inglitele ei alistanud Ta tulevast maailma, millest me räägime,',
        6: 'vaid keegi on kuskil tunnistanud, öeldes: "Mis on inimene, et Sa temale mõtled, või inimese poeg, et Sa tema eest hoolitsed?',
        7: 'Sa tegid ta pisut alamaks Inglitest; Sa ehtisid teda au ja austusega;',
        8: 'kõik Sa panid tema jalge alla!" Sest alistades kõik temale, ei jätnud ta midagi temale alistamata. Aga nüüd me ei näe veel kõike temale alistatuna.',
        9: 'Ent Teda, Kes sai üürikeseks ajaks alamaks Inglitest, Jeesust, me näeme Tema surma kannatamise pärast au ja austusega ehitud, et Ta Jumala armust igaühe eest maitseks surma.',
        10: 'Sest Temale, Kelle pärast ja Kelle läbi on kõik, sobis, et Ta selle, kes palju lapsi ausse viib, nende õndsuse ülemjuhi, teeks täiuslikuks kannatuste kaudu.',
        11: 'Sest niihästi pühitseja kui pühitsetavad on kõik üht Isa; sel põhjusel Tema ka ei häbene neid nimetada vendadeks,',
        12: 'öeldes: "Ma tahan Su nime kuulutada Oma vendadele, keset kogudust Ma tahan laulda Sulle kiitust!"',
        13: 'Ja jälle: "Ma loodan Tema peale!"; ja jälle: "Vaata, siin olen Mina ja lapsed, keda Jumal Mulle on andnud!"',
        14: 'Et nüüd lapsed on liha ja vere osalised, siis Temagi sai otse samal viisil osa sellest, et Ta surma läbi kaotaks selle, kelle võimu all oli surm, see on kuradi,',
        15: 'ja vabastaks need, kes surma kartusest olid kogu eluaja kinni orjapõlves.',
        16: 'Sest ega Ta ometi hoolitse Inglite eest, vaid Ta hoolitseb Aabrahami soo eest!',
        17: 'Sellepärast pidi Ta kõiges saama vendade sarnaseks, et Ta oleks halastaja ja ustav ülempreester teenistuses Jumala ees rahva pattude lepitamiseks.',
        18: 'Sest selles, milles Ta on kannatanud kiusatud olles, võib Ta aidata neid, keda kiusatakse.',
    },
    3: {
        1: 'Sellepärast, pühad vennad, taevase kutsumise osalised, pange tähele meie tunnistuse Apostlit ja ülempreestrit Jeesust,',
        2: 'Kes on ustav Oma ametisseseadjale nagu Mooseski kogu Tema kojas.',
        3: 'Sest Tema on Moosesest niivõrd suurema au vääriline, kuivõrd maja valmistajal on suurem au kui majal.',
        4: 'Sest igal majal on oma valmistaja; aga kes kõik on valmistanud, see on Jumal.',
        5: 'Ja Mooses oli küll ustav sulasena kogu Tema kojas tunnistuseks sellest, mida pidi räägitama,',
        6: 'aga Kristus kui Poeg on Tema koja üle; ja Tema koda oleme meie, kui me julguse ning lootuse kiitlemise hoiame otsani kindla.',
        7: 'Sellepärast nõnda nagu Püha Vaim ütleb: "Täna, kui te kuulete Tema häält,',
        8: 'ärge paadutage oma südameid, nõnda nagu sündis nurina ajal, kiusatuse päeval kõrbes,',
        9: 'kus teie isad Mind kiusasid ning katsusid, kuigi nad olid näinud Minu tegusid nelikümmend aastat,',
        10: 'mispärast Ma vihastusin selle sugupõlve peale ning ütlesin: nemad eksivad alati oma südamega, ent Minu teid nad ei õppinud tundma;',
        11: 'sellepärast Ma vandusin Oma vihas: nad ei pääse mitte Minu hingamisse!"',
        12: 'Katsuge, vennad, et kellelgi teie seast ei oleks kuri uskmatu süda, mis loobub elavast Jumalast,',
        13: 'vaid manitsege üksteist iga päev, niikaua kui veel öeldakse "täna", et ükski teie seast ei paaduks patu pettusest!',
        14: 'Sest me oleme saanud Kristuse osalisiks, kui me vaid otsani kindla hoiame esimese usulootuse.',
        15: 'Kui öeldakse: "Täna, kui te kuulete Tema häält, ärge paadutage oma südameid, nõnda nagu sündis nurina ajal", -',
        16: 'kes siis olid need kuuljad, kes hakkasid nurisema? Kas need ei olnud kõik, kes olid väljunud Egiptusest Moosese juhatusel?',
        17: 'Aga kellele Ta oli vihane nelikümmend aastat? Kas mitte neile, kes olid pattu teinud, kelle kehad langesid kõrbes?',
        18: 'Kellele Ta siis vandus, et nad ei pääse mitte Tema hingamisse? Kas mitte neile, kes olid sõnakuulmatud?',
        19: 'Ja nii me näeme, et nad oma uskmatuse pärast ei võinud sisse saada.',
    },
    4: {
        1: 'Siis kartkem, et niikaua kui tõotus pääseda Tema hingamisse on täitumata, keegi teist kuidagi ei osutuks hiljaks jäänuks.',
        2: 'Sest rõõmusõnum on kuulutatud meile nõnda nagu neilegi. Ent kuuldud sõnast ei olnud neil kasu, sest see ei imbunud usu läbi neisse, kes seda kuulsid.',
        3: 'Sest meie, kes usume, saame hingamisse, nõnda nagu Tema on öelnud: "Siis ma vandusin Oma vihas: nad ei pääse mitte Minu hingamisse!", ehk küll Tema teod olid valmis maailma asutamisest alates.',
        4: 'Sest kuskil on Ta seitsmendast päevast öelnud nõnda: "Ja Jumal hingas seitsmendal päeval kõigist Oma tegudest";',
        5: 'ja siin jälle: "Nad ei pääse mitte Minu hingamisse!"',
        6: 'Et nüüd asi nii on, et mõned pääsevad sinna ja et need, kellele rõõmusõnumit esmalt kuulutati, ei ole sinna sisse saanud sõnakuulmatuse pärast,',
        7: 'siis Ta määrab uuesti ühe päeva "tänapäevaks", öeldes Taaveti kaudu nii pika aja pärast, nagu on enne öeldud: "Täna, kui te kuulete tema häält, ärge paadutage oma südameid!"',
        8: 'Sest kui Joosua nad oleks viinud hingamisse, siis ta ei räägiks teisest, pärastisest päevast.',
        9: 'Seega on Jumala rahval hingamisaeg veel ees.',
        10: 'Sest kes Tema hingamisse on pääsenud, see hingab ka ise oma tegudest, otsekui Jumal Oma tegudest.',
        11: 'Siis olgem agarad sellesse hingamisse minema, et keegi ei langeks sõnakuulmatusse samal eeskujul.',
        12: 'Sest Jumala sõna on elav ja vägev ja teravam kui ükski kaheterane mõõk ning tungib läbi, kuni ta lõhestab hinge ja vaimu, liikmed ja üdi, ja on südame meelsuse ja mõtete hindaja;',
        13: 'ja ükski loodu ei ole temale nähtamatu, vaid kõik on alasti ja paljastatud Tema silma ees; ja Temale tuleb meil aru anda.',
        14: 'Et meil nüüd on suur ülempreester Jeesus, Jumala Poeg, Kes taevad on läbinud, siis pidagem kinni tunnistusest!',
        15: 'Sest meil pole niisugune ülempreester, kellel ei oleks kaastundmust meie nõtrustega, vaid kes kõiges on kiusatud otsekui meie, siiski ilma patuta.',
        16: 'Läki siis julgusega armuaujärje ette, et me saaksime halastust ja leiaksime armu oma abiks õigeks ajaks.',
    },
    5: {
        1: 'Sest iga ülempreester, kes võetakse inimeste seast, seatakse inimeste heaks toimetama teenistust Jumala ees, tooma ande ja ohvreid pattude eest;',
        2: 'ja tema võib säästa mõistmatuid ning eksijaid; on ta ju ise ka nõtruse sees.',
        3: 'Ja selle nõtruse pärast peab tema niisamuti nagu rahva eest, ka iseenese eest ohvrit tooma pattude pärast.',
        4: 'Ka ei võta keegi enesele ise seda au, vaid Jumala kutsel nagu Aarongi.',
        5: 'Nõnda Kristuski ei võtnud Ise Enesele au saada ülempreestriks, vaid Ta sai selle Temalt, Kes Temale ütles: "Sina oled Mu Poeg, täna Ma sünnitasin Sind!",',
        6: 'nõnda nagu Ta teiseski kohas ütleb: "Sina oled preester igavesti Melkisedeki korra järgi!"',
        7: 'Tema ohverdas Oma liha päevil palveid ja anumisi suure hüüdmise ja silmaveega Sellele, Kes Teda võis päästa surmast, ja Tema palvet kuuldi Ta jumalakartuse pärast.',
        8: 'Ja ehk Ta oligi Poeg, õppis Ta sõnakuulmist sellest, mida Ta kannatas.',
        9: 'Ja kui Ta oli saanud täielikuks, sai Tema igavese õndsuse alustajaks kõigile, kes on Temale sõnakuulelikud,',
        10: 'ja Jumal nimetas Tema ülempreestriks Melkisedeki korra järgi.',
        11: 'Sellest oleks meil palju rääkida ning seda on raske sõnadega seletada, sest te olete läinud tuimaks kuulma.',
        12: 'Sest teie, kes aja poolest peaksite olema õpetajad, vajate jälle, et teile õpetataks Jumala sõnade esimesi algeid, ja olete saanud nende aruliseks, kellele läheb tarvis piima, aga mitte tahket rooga.',
        13: 'Sest igaüks, kes veel tarvitab piima, ei saa õieti aru õiguse sõnast, sest ta on alles laps.',
        14: 'Aga täisealiste jaoks on tahke roog, nende jaoks, kelle meeled vilumuse tõttu on harjunud vahet tegema hea ja kurja vahel.',
    },
    6: {
        1: 'Sellepärast jätkem kõrvale algõpetus Kristusest ja püüdkem täiuslikkusele ning ärgem hakakem uuesti rajama alust pöördumisele surnud tegudest ja usule Jumalasse,',
        2: 'õpetusele ristimisest ja käte pealepanemisest, surnute ülestõusmisest ja igavesest hukatusest.',
        3: 'Ja nii me teemegi, kui Jumal lubab.',
        4: 'Sest on võimatu neid, kes korra olid valgustatud ning maitsesid taevalist andi ja said osa Pühast Vaimust,',
        5: 'ja maitsesid Jumala head sõna ja tulevase maailmaajastu väge',
        6: 'ja siis ära taganesid, uuesti tuua meeleparandamisele, sellepärast et nad iseeneste kahjuks Jumala Poja risti löövad ja naeruks panevad.',
        7: 'Sest maa, mis joob enesesse rikkalikult sadanud vihma ja kasvatab tarvilist vilja neile, kes seda harivad, saab õnnistuse Jumalalt;',
        8: 'kuid maa, mis kannab kibuvitsu ja ohakaid, on kõlbmatu ja lähedal needusele, ja lõppeks ta põletatakse.',
        9: 'Aga, armsad, teie suhtes me usume seda, mis on parem ja soodus õndsusele, kuigi me räägime nõnda.',
        10: 'Sest Jumal ei ole ülekohtune, et Ta unustaks ära teie teod ja armastuse, mida olete osutanud Tema nimele, kui te pühadele abiks olite ja veelgi olete.',
        11: 'Aga me ihaldame seda, et te igaüks osutaksite sama indu täieliku lootuse säilitamiseks otsani;',
        12: 'et te ei läheks loiuks, vaid järgiksite neid, kes usu ja pika meele tõttu pärivad selle, mis on tõotatud.',
        13: 'Sest kui Jumal Aabrahamile andis tõotuse, vandus Ta Iseenese juures, sest ei olnud kedagi suuremat, kelle juures Ta oleks võinud vanduda,',
        14: 'ning ütles: "Tõesti, õnnistusega Ma õnnistan sind ja teen sind väga paljuks!"',
        15: 'Ja nii Aabraham ootas kannatlikult ning sai tõotuse kätte.',
        16: 'Sest inimesed vannuvad suurema juures ja vanne on neile kinnituseks kui kõige vasturääkimise lõpetus.',
        17: 'Nii on Jumal selleks, et tõotuse pärijaile veel selgemini näidata oma nõu kindlust, vannet tarvitanud vahendiks,',
        18: 'et kahe kõikumatu asja läbi, milles Jumalal on võimatu valetada, oleks vägev julgustus meil, kes oleme usaldanud kinni haarata eelolevast lootusest,',
        19: 'mis meile on otsekui hinge ankur, kindel ja tugev ning ulatub sissepoole eesriide taha,',
        20: 'kuhu eeljooksjana meie heaks on läinud sisse Jeesus, kui ta sai ülempreestriks igavesti Melkisedeki korra järgi.',
    },
    7: {
        1: 'Sest see Melkisedek - Saalemi kuningas, kõige kõrgema Jumala preester, kes tuli vastu Aabrahamile, kui see oli koju minemas pärast võitu kuningate üle, ja õnnistas teda,',
        2: 'kellele ka Aabraham jagas kümnist kõigest saagist ja kes on esmalt, nagu teda tõlgitsetakse, "Õiguse kuningas", aga siis ka Saalemi kuningas, see on "Rahu kuningas",',
        3: 'kes on isata, emata, ilma suguvõsata, ilma päevade alguseta ja ilma eluotsata, ent kes on sarnastatud Jumala Pojaga - jääb preestriks igavesti.',
        4: 'Vaadake siis, kui suur on see, kellele ka peavanem Aabraham andis saagist kümnist.',
        5: 'On ju neil Leevi poegadelgi, kes saavad preestriameti, käsk võtta kümnist käsuõpetuse järgi rahva, see on oma vendade käest, ehk küll nemadki on lähtunud Aabrahami niudeist.',
        6: 'Kuid see, kes ei põlvnenudki nendest, võttis kümnise Aabrahami käest ja õnnistas teda, kellel olid tõotused.',
        7: 'Ent vasturääkimata on selge, et alam saab õnnistuse ülemalt.',
        8: 'Ja siin võtavad kümnist surelikud inimesed, aga seal see, kellest tunnistatakse, et ta elab.',
        9: 'Ja Aabrahami kaudu on, niiöelda, Leevigi, kes võtab kümnist, pidanud kümnist maksma;',
        10: 'sest ta oli veel isa niudeis, kui Melkisedek temale vastu tuli.',
        11: 'Kui nüüd täiuslikkus oleks leviitide preestriameti kaudu olnud saavutatud - sest sellele on rajatud rahva käsuõpetus - mis vajadust siis veel oli, et teistsugune preester tõusis Melkisedeki korra järgi ega nimetatud teda Aaroni korra järgi?',
        12: 'Sest preestriameti muutmisega sünnib paratamatult ka käsuõpetuse muutus.',
        13: 'Sest See, Kellest seda öeldakse, on pärit teisest suguharust, kellest veel ükski ei ole saanud altari juurde.',
        14: 'On ju teada, et meie Issand on tärganud Juudast, kelle suguharule Mooses ei ole midagi kõnelnud preestriametist.',
        15: 'Ja asi saab veel palju selgemaks, kui tõuseb teistsugune Melkisedeki sarnane Preester,',
        16: 'Kes ei ole lihaliku käsusõna käsku mööda saanud preestriks, vaid hääbumatu elu väge mööda.',
        17: 'Sest tunnistatakse: "Sina oled preester igavesti Melkisedeki korra järgi!"',
        18: 'Endise käsusõna tühistus sünnib ju selle tõttu, et see oli jõuetu ja kasutu -',
        19: 'ei ole ju käsk midagi viinud täiuslikkusele - ent asemele seatakse parem lootus, mille kaudu me tuleme Jumala ligi.',
        20: 'Ja niivõrd kui see ei tekkinud ilma vandeta - sest need on saanud preestreiks ilma vandeta,',
        21: 'Tema aga vandega selle seadmisel, kes Temale ütles: "Issand on vandunud ja Tema ei kahetse seda mitte: Sina oled preester igavesti!" -',
        22: 'Sedavõrd on palju parem ka leping, mille käemeheks on saanud Jeesus.',
        23: 'Oli ju neid palju, kes said preestreiks, sellepärast et surm neid keelas jäämast.',
        24: 'Aga Temal on selle tõttu, et Ta jääb igavesti, preestriamet, mis ei lähe kellegi teise kätte.',
        25: 'Sellepärast võib Ta ka täielikult päästa need, kes tulevad Tema läbi Jumala juurde, elades aina selleks, et kosta nende eest.',
        26: 'Niisugune Ülempreester peabki ju meil olema: püha, veatu, laitmatu, eraldatud patustest ja kõrgemale saanud kui taevad,',
        27: 'Kellel ei ole mitte iga päev vaja nõnda nagu ülempreestril esiti tuua ohvreid enese pattude eest ja siis rahva pattude eest; sest seda on Ta igaks puhuks teinud, kui Ta Iseenese tõi ohvriks.',
        28: 'Sest käsk seab nõdrad inimesed ülempreestreiks, aga vande sõna, mis on hilisem käsuõpetusest, seab Poja, Kes on täiuslikuks saanud igaveseks.',
    },
    8: {
        1: 'Aga peaasi selles, millest me kõneleme, on see: meil on selline Ülempreester, Kes istub Ausuuruse istme paremal käel taevas,',
        2: 'pühamu ja tõelise telgi ametitalitaja, mille on ehitanud Jumal ja mitte inimene.',
        3: 'Sest iga ülempreester seatakse ohverdama ande ja ohvreid, mispärast on paratamata vajalik, et Tal oleks midagi ning seda, mida ohverdada.',
        4: 'Kui Ta nüüd oleks maa peal, ei Ta siis olekski preester, sest on olemas neid, kes käsuõpetuse järgi ohverdavad ande',
        5: 'ja kes teenivad selles, mis on taevase pühamu kuju ja vari, nagu Moosesele ilmutati, kui ta hakkas telki valmistama. Sest nii öeldi talle: "Vaata, et sa kõik teed selle eeskuju järgi, mis sulle mäel näidati!"',
        6: 'Aga nüüd on Tema saanud seda kallima ameti, mida parema lepingu vahemees Ta ka on, mis on rajatud parematele tõotustele.',
        7: 'Sest kui esimene leping oleks olnud laitmatu, ei siis oleks otsitud aset teisele.',
        8: 'Sest neid laites ütleb prohvet neile: "Vaata, päevad tulevad, ütleb Issand, mil Ma teen Iisraeli sooga ja Juuda sooga uue lepingu:',
        9: 'mitte selle lepingu sarnase, mille Ma tegin nende vanematega sel päeval, mil Ma võtsin nad kättpidi, et viia nad välja Egiptusemaalt - sest nad ei jäänud Minu lepingusse ja nii Minagi ei hoolinud neist, ütleb Issand -',
        10: 'vaid leping, mille Ma teen Iisraeli sooga pärast neid päevi, ütleb Issand, on niisugune: Ma panen neile meelde Oma käsud ja kirjutan need neile südamesse; siis Ma olen neile Jumalaks ja nemad on Mulle rahvaks!',
        11: 'Siis ei õpeta keegi enam oma kaaskodanikku ega vend oma venda, öeldes: "Tunne Issandat!", sest nad kõik tunnevad Mind, niihästi nende pisukesed kui nende suured.',
        12: 'Sest Ma olen armuline nende ülekohtustele tegudele ega tuleta enam meelde nende patte!"',
        13: 'Kui ta nimetab uut, siis on ta esimese tunnistanud vananenuks. Aga mis vananeb ja iganeb, on hävimisele ligi!',
    },
    9: {
        1: 'Esimesel lepingul olid ju ka oma Jumalateenistuse korraldused ja oma maine pühamu.',
        2: 'Sest enne valmistati esimene telk, milles olid küünlajalg ja laud ja vaateleivad laual; seda kutsutakse "pühaks paigaks."',
        3: 'Ent teise eesriide taga oli telk, mida kutsutakse "kõige pühamaks paigaks."',
        4: 'Seal oli kuldne suitsutusaltar ja seaduselaegas, mis oli üleni kullaga karratud; selle sees oli kuldkruus mannaga ja Aaroni kepp, mis oli õitsenud, ja seaduselauad.',
        5: 'Ent laeka peal olid auhiilguse keerubid, kes varjasid lepituskaant. Sellest kõigest ei ole nüüd tarvis üksikasjalikult rääkida.',
        6: 'Et need kõik nõnda on korrastatud, siis lähevad eestelki alati preestrid, kes toimetavad Jumalateenistusi,',
        7: 'aga teise läheb korra aastas üksnes ülempreester, mitte ilma vereta, mille ta ohverdab oma ja rahva eksimuste eest.',
        8: 'Sel kombel näitab Püha Vaim, et tee pühasse paika veel ei ole avatud, niikaua kui esimene telk veel on olemas.',
        9: 'See on praeguse aja kohta võrdum, mille kohaselt ohverdatakse ande ja ohvreid, mis ei suuda teha südametunnistuse poolest täiuslikuks seda, kes toimetab teenistust,',
        10: 'vaid mis samuti nagu toidud ja joogid ja mitmesugused pesemised on ainult liha korraldused, kehtivad seniks, kui kätte jõuab uuendatud korra aeg.',
        11: 'Aga Kristus, kui Tema tuli tulevaste heade andide Ülempreestrina, suurema ja täiuslikuma telgiga, mis ei ole kätega tehtud, see on, mis ei ole pärit sellest loomisest,',
        12: 'ja ka mitte sikkude ega vasikate verega, vaid Iseenese Verega, läks ükskord sinna pühasse paika ning saavutas igavese lunastuse.',
        13: 'Sest kui sikkude ja härgade veri ja lehma tuhk, mis riputatakse nende peale, kes on rüvetunud, pühitseb liha puhtuseks,',
        14: 'kui palju enam Kristuse Veri, Kes igavese Vaimu läbi Iseenese veatuna ohverdas Jumalale, puhastab meie südametunnistuse surnud tegudest teenima elavat Jumalat.',
        15: 'Ja sellepärast on Tema uue lepingu vahemees, et pärast Tema surma, mis oli lunastuseks esimese lepingu ajal olnud üleastumistest, need, kes on kutsutud, kätte saaksid igavese pärandi.',
        16: 'Sest seal, kus on olemas testament, on hädavajalik, et tõendataks ka testamenditegija surm.',
        17: 'Sest testament hakkab kehtima pärast surma; sest see ei ole kunagi jõus, niikaua kui testamenditegija on elus.',
        18: 'Sellepärast ei ole ka esimest lepingut pühitsetud ilma vereta.',
        19: 'Sest kui Mooses kõigele rahvale oli ette lugenud kogu käsu käsuõpetuse järgi, võttis ta vasikate ja sikkude vere ühes vee ja punase villa ja iisopiga ja piserdas seda niihästi raamatu enese kui ka kõige rahva peale',
        20: 'ning ütles: "See on selle lepingu veri, mille Jumal on seadnud teie jaoks!"',
        21: 'Ja samuti ta piserdas verd ka telgi ja kõigi Jumalateenistuseriistade peale.',
        22: 'Ja peaaegu kõik puhastatakse verega käsuõpetuse järgi, ja ilma verd valamata ei ole andeksandmist olemas.',
        23: 'Nii on siis tarvis, et taevalike asjade kujud puhastatakse sel teel, aga taevasi asju endid puhastatakse paremate ohvritega kui need.',
        24: 'Sest Kristus ei läinud kätega tehtud pühamusse kui tõelise püha paiga kujusse, vaid taevasse Enesesse, et nüüd ilmuda Jumala palge ette meie eest,',
        25: 'aga mitte Ennast mitu korda ohverdama, nõnda nagu ülempreester igal aastal läks pühasse paika võõra verega,',
        26: 'sest muidu oleks Ta pidanud mitu korda kannatama maailma rajamisest alates; aga nüüd on Ta maailmaajastute lõpul korra ilmunud, et Oma ohvriga kaotada patt.',
        27: 'Ja otsekui inimestele on määratud kord surra, aga pärast seda kohus,',
        28: 'nõnda ka Kristus, Kes üks kord tõi Enese ohvriks, et ära võtta paljude patud, ilmub teist korda ilma patuta neile, kes Teda ootavad õndsuseks.',
    },
    10: {
        1: 'Käsk, olles ainult tulevaste hüvede vari, aga mitte asjade täiskuju ise, ei või iialgi samade iga-aastaste ohvritega, mida ühtelugu ohverdatakse, teha täiuslikuks nende toojaid,',
        2: 'sest eks muidu oleksid ju ohvrite toomised lõppenud, sellepärast et neil, kes toimetavad jumalateenistust, ei oleks enam mingit patust südametunnistust, kui nad kord on puhtaks tehtud.',
        3: 'Ent ohvritega tuletatakse iga aasta patte meelde.',
        4: 'Sest on võimatu, et härgade ja sikkude veri võib patud ära võtta.',
        5: 'Sellepärast Ta maailma tulles ütleb: "Ohvrit ega andi Sa ei tahtnud, aga Sa valmistasid Mulle ihu:',
        6: 'põletus- ja patuohvrid ei olnud Sulle meelepärast!',
        7: 'Siis Ma ütlesin: vaata, Ma tulen - rullraamatus on Minust kirjutatud - tegema Su tahtmist, oh Jumal!"',
        8: 'Kuna Ta eespool ütleb: "Ohvreid ja ande ning põletus- ja patuohvreid Sa ei tahtnud ega olegi need Su meele järgi, kuigi neid käsu järgi tuuakse",',
        9: 'siis ütleb Ta pärast: "Vaata, Ma tulen tegema Su tahtmist!" Sellega Ta tunnistab tühjaks esimese ohvri, et panna kehtima teine.',
        10: 'Selles tahtmises oleme meiegi pühitsetud Jeesuse Kristuse Ihu ohvriga ühel hoobil.',
        11: 'Ja iga preester seisab päevast päeva oma ametis ja ohverdab sageli samu ohvreid, mis iialgi ei või patte ära võtta;',
        12: 'aga Tema, kui Ta üheainsa ohvri oli viinud pattude eest, on istunud jäädavalt Jumala paremale käele',
        13: 'ja ootab nüüd ainult, kuni Ta vaenlased pannakse Tema jalgealuseks järiks.',
        14: 'Sest ühe ohvriga on Ta jäädavalt teinud täiuslikeks need, keda pühitsetakse.',
        15: 'Seda tunnistab meile ju ka Püha Vaim; sest kui Ta oli öelnud:',
        16: '"Niisugune on leping, mille Ma teen nendega pärast neid päevi, ütleb Issand: Ma panen neile südamesse Oma käsud ja kirjutan need neile meelde',
        17: 'ega mäleta enam nende patte ja ülekohtutegusid!"',
        18: 'Aga kus need on andeks antud, seal ei ole enam tarvis ohvrit nende eest.',
        19: 'Nii on meil siis, vennad, Jeesuse Veres julgus sissepääsuks pühasse paika;',
        20: 'ja selle on Ta meile avanud uueks ja elavaks teeks eesriide, see on Oma liha kaudu;',
        21: 'ja meil on suur Preester Jumala koja üle.',
        22: 'Astugem siis ligi tõelise südamega, täielikus usus, südame poolest piserdamisega puhastatud kurjast südametunnistusest,',
        23: 'ja ihu poolest pestud puhta veega, pidagem kõikumata kinni lootuse tunnistusest. Sest ustav on See, Kes seda on tõotanud.',
        24: 'Ja pidagem üksteist silmas õhutamiseks armastusele ja headele tegudele.',
        25: 'Ning ärgem jätkem maha oma koguduse kooskäimisi, nõnda nagu mõnel on kombeks, vaid manitsegem üksteist, ja seda enam, et näete selle päeva lähenevat.',
        26: 'Sest kui me meelega pattu teeme, pärast seda kui oleme saanud tõe tunnetuse, siis ei jää enam mingit ohvrit üle pattude eest;',
        27: 'vaid mingi hirmus kohtu ootamine ja äge tuli, mis tahab ära süüa vastupanijad.',
        28: 'Kui keegi rikub Moosese käsku, siis peab ta ilma armuta surema kahe või kolme tunnistaja sõna peale,',
        29: 'kui palju hirmsama nuhtluse te arvate siis ära teeninud olevat selle, kes Jumala Poega jalgadega tallab ega pea pühaks lepingu Verd, millega ta on pühitsetud, ja teotab armu Vaimu?',
        30: 'Me tunneme ju Seda, Kes ütleb: "Minu käes on kättemaks, Mina tasun kätte!" ja taas: "Issand mõistab kohut Oma rahvale!"',
        31: 'Hirmus on elava Jumala kätte langeda!',
        32: 'Aga tuletage meelde endisi päevi, mil teie, olles valgustatud, talusite palju kannatamiste võitlust,',
        33: 'kord nii, et te teotamiste ja viletsuste läbi olite tehtud maailma naeruks, kord jälle nii, et saite nende osalisteks, kellel oli sama saatus.',
        34: 'Sest te olete ühes vangidega kannatanud ja rõõmuga vastu võtnud oma vara riisumise, teades, et teil on parem ja jäädav vara taevas.',
        35: 'Ärge siis heitke ära oma julgust, mis saab suure palga.',
        36: 'Sest kannatlikkust läheb teile tarvis, et teie, tehes Jumala tahtmist, saaksite kätte tõotuse.',
        37: 'Sest "veel üsna pisut, pisut aega, siis tuleb See, Kes peab tulema ega viivita mitte!',
        38: 'Aga Minu õige peab usust elama, ja kui ta hakkab kõhklema, siis ei ole Minu hingel temast head meelt!"',
        39: 'Ent meie ei ole need, kes kõhklevad hukatuseks, vaid need, kes usuvad hinge päästmiseks!',
    },
    11: {
        1: 'Aga usk on kindel usaldus selle vastu, mida oodatakse, ja veendumus selles, mida ei nähta.',
        2: 'Selle kohta on ju vanad saanud tunnistuse.',
        3: 'Usu kaudu me tunneme, et maailmad on valmistatud Jumala sõna läbi, nii et mitte sellest, mida võib näha, ei ole tekkinud see, mida nähakse.',
        4: 'Usu läbi tõi Aabel Jumalale parema ohvri kui Kain, ja usu kaudu ta sai tunnistuse, et tema oli õige, kui Jumal andis tunnistuse tema andide kohta, ja usu kaudu ta räägib veel pärast surmagi.',
        5: 'Usu läbi võeti ära Eenok, et ta surma ei näeks, ja teda ei leitud enam, sest Jumal oli ta ära võtnud. Sest enne äravõttu oli ta juba saanud tunnistuse, et ta oli Jumalale meelepärane.',
        6: 'Aga ilma usuta on võimatu olla meelepärane; sest kes Jumala juurde tuleb, peab uskuma, et Tema on olemas ja et Ta annab palga neile, kes Teda otsivad.',
        7: 'Usu kaudu sai Noa ilmutuse sellest, mida veel ei olnud näha, ja ehitas pühas kartuses laeva oma perekonna päästmiseks; ja selle kaudu ta mõistis hukka maailma ning sai selle õiguse pärijaks, mis tuleb usust.',
        8: 'Usu läbi kuulas Aabraham sõna, kui teda kutsuti välja minema paika, mille ta pidi saama pärandiks; ja ta läks välja ilma teadmata, kuhu ta läheb.',
        9: 'Usu läbi asus ta võõrana elama tõotusemaale otsekui võõrale maale ja elas telkides ühes Iisaki ja Jaakobiga, kes olid sama tõotuse kaaspärijad;',
        10: 'sest ta ootas linna, millel on alused ja mille ehitaja ning valmistaja on Jumal.',
        11: 'Usu läbi sai isegi Saara rammu soo rajamiseks ja pealegi üle oma ea, sellepärast et ta pidas ustavaks teda, kes tõotuse oli andnud.',
        12: 'Sellepärast sündis ka ühest ja pealegi elatanud mehest nii palju nagu taevas tähti ja nagu mere ääres liiva, mida ei saa ära lugeda.',
        13: 'Usus need kõik surid ega saanud tõotusi kätte, vaid nägid neid kaugelt ja teretasid neid ning tunnistasid endid olevat võõrad ja majalised maa peal.',
        14: 'Sest need, kes seda ütlevad, näitavad, et nad otsivad kodumaad.',
        15: 'Ja kui nad oleksid mõelnud seda kodumaad, kust nad olid väljunud, siis oleks neil ju olnud juhust minna tagasi.',
        16: 'Ent nüüd nad igatsevad paremat kodumaad, see on taevast; seepärast ei ole Jumalal neist häbi ja Ta laseb Ennast nimetada nende Jumalaks; sest Ta on neile valmistanud linna.',
        17: 'Usu läbi viis Aabraham ohvriks Iisaki, kui teda katsuti, ja ohverdas selle ainusündinu, kui ta oli saanud tõotused',
        18: 'ning kui temale oli öeldud: "Iisakist loetakse sinu sugu!"',
        19: 'Sest ta mõtles, et Jumal on võimeline ka surnuist üles äratama; selle mõistukujuks ta sai tema ka tagasi.',
        20: 'Usu läbi õnnistas ka Iisak Jaakobit ja Eesavit tulevaste asjade suhtes.',
        21: 'Usu läbi õnnistas Jaakob surres kumbagi Joosepi poegadest ja palvetas oma kepi pära najal.',
        22: 'Usu läbi tuletas Joosep oma eluotsal meelde Iisraeli laste väljumist ja tegi korralduse oma luude kohta.',
        23: 'Usu läbi varjasid vanemad Moosest pärast ta sündimist kolm kuud, sest nad nägid ta ilusa lapse olevat ega kartnud kuninga käsku.',
        24: 'Usu läbi keeldus Mooses, kui ta suureks sai, kandmast vaarao tütrepoja nime,',
        25: 'pidades paremaks ühes Jumala rahvaga kannatada viletsust kui üürikest aega nautida paturõõmu,',
        26: 'arvates Kristuse teotust suuremaks rikkuseks kui Egiptuse aarded; sest ta tõstis oma silmad tasu poole.',
        27: 'Usu läbi ta jättis maha Egiptuse ega kartnud kuninga viha, sest otsekui nähes teda, kes on nähtamatu, püsis ta kindlana.',
        28: 'Usu läbi ta pidas Paasapüha ja vere piserdust, et esmasündinute surmaja ei puudutaks neid.',
        29: 'Usu läbi nad läksid Punasest merest läbi nagu kuiva maad mööda, mida ka egiptlased katsusid teha, aga uppusid.',
        30: 'Usu läbi langesid Jeeriko müürid, kui seitse päeva oli käidud nende ümber.',
        31: 'Usu läbi ei saanud hoor Raahab hukka ühes sõnakuulmatutega, kui ta salakuulajad oli rahuga vastu võtnud.',
        32: 'Ja mida ma veel ütleksin? Mul puudub aeg jutustada Giideonist ja Baarakist ja Simsonist ja Jeftast ja Taavetist ja Saamuelist ja prohvetitest,',
        33: 'kes usu läbi võitsid ära kuningriigid, viisid täide õiguse, said kätte tõotused, sulgesid lõukoerte lõuad,',
        34: 'kustutasid tule väe, pääsesid ära mõõgatera eest, said nõtrusest tugevaks, said vägevaks sõjas, ajasid pakku võõraste sõjahulgad.',
        35: 'Naised said tagasi oma surnud ülestõusmise läbi. Teised lasksid ennast piinata ega võtnud vastu vabastamist, et saaksid parema ülestõusmise osalisiks.',
        36: 'Teised said kogeda pilget ja rooska, peale selle ahelaid ja vangitorni.',
        37: 'Neid on kividega visatud, piinatud, lõhki saetud, mõõgaga surmatud; nad on lambanahas ja kitsenahas käinud ühest kohast teise, puuduses, viletsuses, kurja kannatades, nemad,',
        38: 'kelle väärt maailm ei olnud. Nad eksisid ümber kõrbetes ja mägedel ja koobastes ja maa-aukudes.',
        39: 'Ja need kõik, olles usu läbi saanud tunnistuse, ei saavutanud ometi mitte seda, mis oli tõotatud;',
        40: 'sest Jumal oli meile varunud midagi paremat, et nad ilma meieta ei pääseks täielikkusesse.',
    },
    12: {
        1: 'Sellepärast meiegi, et nii suur pilv tunnistajaid on meie ümber, pangem maha kõik koorem ja meid nii hõlpsasti takerdav patt ning jookskem kannatlikkusega meile määratud võidujooksmist,',
        2: 'vaadates usu alustajale ja täidesaatjale Jeesusele, Kes risti kannatas Temale oodatava rõõmu asemel, häbist hoolimata, ja on istunud Jumala aujärje paremale käele.',
        3: 'Kujutlege ometi Teda, Kes niisugust vastuhakkamist Enese vastu on saanud kannatada patustelt, et te ei väsiks ega läheks araks oma hinges.',
        4: 'Teie ei ole veel vereni vastu pannud võideldes patuga',
        5: 'ja olete unustanud manitsuse, mis teile otsekui lastele ütleb: "Mu poeg, ära põlga Issanda karistust ja ära saa araks, kui Tema sind noomib!',
        6: 'Sest keda Issand armastab, seda Ta karistab; Ta peksab igat poega, keda Ta vastu võtab."',
        7: 'Taluge karistust kasvatuseks: Jumal kohtleb teid kui poegi; sest milline poeg on see, keda isa ei karista?',
        8: 'Ent kui te olete ilma karistuseta, millest kõik on osa saanud, siis te olete värdjad ja mitte pojad.',
        9: 'Pealegi on meile meie lihased isad olnud karistajaiks ja me oleme neid kartnud; kas me palju enam ei tahaks alistuda vaimude Isale ning elada?',
        10: 'Sest nemad on küll meid mõnd päeva oma heaksarvamist mööda karistanud, aga Tema karistab meid tõesti selle hea otstarbega, et me saaksime osa Tema pühadusest.',
        11: 'Aga mingi karistus, kui see on käes, ei näi olevat rõõmuks, vaid on kurbuseks; aga pärast toob see neile, kes sellega on õpetatud, õiguse rahuvilja.',
        12: 'Seepärast ajage jälle sirgu lõdvad käed ja halvatud põlved',
        13: 'ja õgvendage teerajad oma jalgadele, et see, mis lonkav, ei nikastuks, vaid ennemini saaks terveks.',
        14: 'Nõudke rahu kõikidega ja pühitsust; ilma selleta ei saa ükski Issandat näha.',
        15: 'Ja pange tähele, et keegi ei jääks ilma Jumala armust, et ükski viha juur ei kasvaks üles ega tooks tüli ja selle läbi paljud ei rüvetuks,',
        16: 'et keegi ei oleks hooraja või roojane, kes nagu Eesav üheainsa kõhutäie eest andis käest esmasünniõiguse.',
        17: 'Sest te teate, kuidas ta pärast küll tahtis pärida õnnistust, aga siis hüljati kui kõlvatu; sest ta ei leidnud mahti meeleparanduseks, ehk ta seda küll silmapisaratega otsis.',
        18: 'Sest te ei ole astunud käega katsutava ja tules põleva mäe ligi, ei pimeduse ega pilkase pimeduse, ei maru,',
        19: 'ei pasuna helina ega niisuguse sõnade hääle ligi, mille kuuljad palusid, et neile sõna enam ei räägitaks;',
        20: 'sest nemad ei suutnud taluda seda keeldu: "Isegi kui üks loom peaks puutuma mäe külge, siis visatagu ta kividega surnuks!";',
        21: 'ja nii hirmus oli see nähtus, et Mooses ütles: "Ma olen ehmunud ja värisen!";',
        22: 'vaid te olete tulnud Siioni mäe ligi ja elava Jumala linna, taevase Jeruusalemma juurde ja lugematu hulga Inglite juurde,',
        23: 'ja esmasündinute piduliku kogu ning koguduse juurde, kes on kirja pandud taevasse, ja Jumala, kõikide kohtumõistja juurde, ja õigete vaimude juurde, kes on saanud täiuslikeks,',
        24: 'ja uue lepingu vahemehe Jeesuse juurde ja Piserdamisvere juurde, mis paremini räägib kui Aabeli veri.',
        25: 'Katsuge, et teiegi teda ei hülga, Kes räägib! Sest kui ei ole pääsenud need, kes maapealse kõneleja hülgasid, kui palju vähem pääseme meie, kui me pöördume ära Temast, kes on taevastest,',
        26: 'Kelle hääl tookord pani kõikuma maa, aga Kes nüüd on tõotanud ja öelnud: "Veel kord Ma panen värisema mitte ainult maa, vaid ka taeva!"',
        27: 'Ent "veel kord" näitab, et see, mis kõigub, peab muutuma, sest ta on loodud, et püsiks see, mida ei saa kõigutada.',
        28: 'Seepärast, saades kuningriigi, mis ei kõigu, olgem tänulikud ja teenigem seega Jumalat tema meelt mööda pelglikkuse ja aukartusega.',
        29: 'Sest meie Jumal on hävitav tuli!',
    },
    13: {
        1: 'Vendade armastus jäägu püsima!',
        2: 'Ärge unustage külalislahkust, sest selle läbi on mõningad ilma teadmata külalisteks vastu võtnud Ingleid.',
        3: 'Pidage meeles vange, otsekui oleksite kaasvangid, ja vaevatuid, sest ka teie olete veel ihus.',
        4: 'Abielu olgu igapidi au sees ja abieluvoodi rüvetamata! Sest Jumal nuhtleb hoorajaid ja abielurikkujaid.',
        5: 'Teie meelelaad olgu rahaahnuseta; olge rahul sellega, mis teil on. Sest Tema on öelnud: "Ma ei hülga sind ega jäta sind maha!"',
        6: 'Nii võime siis julgesti öelda: "Issand on minu abimees, ei ma karda! Mis võib inimene mulle teha?"',
        7: 'Mõelge oma juhatajaile, kes teile on rääkinud Jumala sõna, pannes tähele nende eluotsa järgige nende usku!',
        8: 'Jeesus Kristus on Seesama, eile ja täna ja igavesti!',
        9: 'Ärge laske endid vintsutada mitmelaadiliste ja võõraste õpetustega; sest hea on, et süda kinnitatakse armu läbi, aga mitte toitudega, millest ei ole saanud kasu need, kes nende määruste järgi käivad.',
        10: 'Meil on ohvrialtar, kust toidust võtta ei ole luba neil, kes telgis peavad teenistust.',
        11: 'Sest nende loomade kehad, kelle vere ülempreester viib ohvriks patu eest pühasse paika, põletatakse väljaspool leeri.',
        12: 'Seepärast on ka Jeesus, et pühitseda rahvast Oma Vere läbi, kannatanud väljaspool väravat.',
        13: 'Siis mingem nüüd Tema juurde väljapoole leeri ning kandkem Tema teotust.',
        14: 'Sest meil pole siin jäädavat linna, vaid meie otsime tulevast.',
        15: 'Viigem siis nüüd Tema kaudu alati Jumalale kiitusohvrit, see on nende huulte vilja, kes tunnistavad Tema nime.',
        16: 'Ärge unustage head teha ja osadust pidada, sest sellised ohvrid on Jumala meele järgi.',
        17: 'Olge sõnakuulelikud oma juhatajaile ja alistuge neile; sest nemad valvavad teie hingi nõnda nagu need, kellel tuleb aru anda, et nad teeksid seda rõõmuga ja mitte ohates; sest teil ei oleks sellest kasu.',
        18: 'Palvetage meie eest! Sest me oleme veendunud selles, et meil on hea südametunnistus ja me tahame kõiges käituda kaunisti.',
        19: 'Eriti ma palun seda teha selleks, et mind rutemini antaks teile tagasi.',
        20: 'Aga rahu Jumal, Kes surnuist on üles toonud igavese lepingu Vere läbi lammaste suure Karjase, meie Issanda Jeesuse,',
        21: 'varustagu teid kõige heaga Tegema Tema tahtmist ja saatku teie sees korda seda, mis on Tema meelt mööda, Jeesuse Kristuse läbi, Kellele olgu austus ajastute ajastuteni! Aamen.',
        22: 'Aga ma palun teid, vennad, võtke heaks see manitsussõna! Ma olen teile ju lühidalt kirjutanud.',
        23: 'Teadke, et meie vend Timoteos on jälle vaba. Temaga ühes, kui ta varsti tuleb, saan ma teid näha.',
        24: 'Tervitage kõiki oma juhatajaid ja kõiki pühasid! Teid tervitavad Itaalia vennad.',
        25: 'Arm olgu teie kõikidega!',
    },
}
